124	ge::graphStatus InferOutDataTypeSameWithFirstInputFunc(InferDataTypeContext *context) {
125	  const auto compute_node_info = context->GetComputeNodeInfo();
126	  GE_ASSERT_TRUE(compute_node_info != nullptr, "Get null compute_node_info.");
127	
128	  const auto input0_dtype = context->GetInputDataType(0);
129	  GE_ASSERT_TRUE(input0_dtype != ge::DT_UNDEFINED, "Get undefined datatype of input_0, op_name:[%s], op_type:[%s].",
130	                 context->GetComputeNodeInfo()->GetNodeName(), context->GetComputeNodeInfo()->GetNodeType());
131	
132	  const auto output_num = context->GetComputeNodeOutputNum();
133	  for (size_t i = 0U; i < output_num; ++i) {
134	    GE_ASSERT_GRAPH_SUCCESS(context->SetOutputDataType(i, input0_dtype),
135	                            "Failed to set datatype of output_%zu, op_name:[%s], op_type:[%s].", i,
136	                            compute_node_info->GetNodeName(), compute_node_info->GetNodeType());
137	  }
138	  return ge::GRAPH_SUCCESS;
139	}
