264	void OpImplSpaceRegistryImpl::MergeTypesToCtImpl(OpTypesToImplMap &merged_impl,
265	                                                 const OpTypesToCtImplMap &src_impl) const {
266	  for (const auto &iter : src_impl) {
267	    const auto op_type = iter.first;
268	    GELOGD("Merge ct types to impl, op type %s", op_type.GetString());
269	    auto merge_iter = merged_impl.find(op_type);
270	    if (merge_iter == merged_impl.end()) {
271	      auto &merged_funcs = merged_impl[op_type];
272	      merged_funcs.calc_op_param = iter.second.calc_op_param;
273	      merged_funcs.gen_task = iter.second.gen_task;
274	      merged_funcs.check_support = iter.second.check_support;
275	      merged_funcs.op_select_format = iter.second.op_select_format;
276	      merged_funcs.get_op_support_info = iter.second.get_op_support_info;
277	      merged_funcs.get_op_specific_info = iter.second.get_op_specific_info;
278	      GELOGD("Merge ct version to impl, op type %s, impl version[%zu], ct version[%zu]", op_type.GetString(),
279	             merged_funcs.version, iter.second.version);
280	      merged_funcs.version = iter.second.version;
281	      continue;
282	    } else {
283	      // 后续IMPL_CT_OP合并到IMPL_OP后删除
284	      // 当前是临时兼容，以version区分IMPL_CT_OP、IMPL_OP
285	      auto &merged_funcs = merged_impl[op_type];
286	      GELOGD("Merge ct version to impl, op type %s, impl version[%zu], ct version[%zu]", op_type.GetString(),
287	             merged_funcs.version, iter.second.version);
288	      merged_funcs.version = iter.second.version;
289	    }
290	    const auto &src_funcs = iter.second;
291	    MergeCtFunctions(merge_iter->second, src_funcs, op_type.GetString());
292	  }
